public with sharing class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    private static final Pattern CURRENCY_PATTERN = Pattern.compile('^[A-Z]{3}$');

    private static class RateResponse {
        public String base;
        public String date;
        public Map<String, Decimal> rates;
    }

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (baseCurrency == null || quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Base currency and quote currencies are required');
        }

        String baseNorm = baseCurrency.trim().toUpperCase();
        if (!CURRENCY_PATTERN.matcher(baseNorm).matches()) {
            throw new ExchangeRateException('Invalid base currency: ' + baseCurrency);
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String q : quoteCurrencies) {
            if (q == null) {
                throw new ExchangeRateException('Quote currency is null');
            }
            String qNorm = q.trim().toUpperCase();
            if (!CURRENCY_PATTERN.matcher(qNorm).matches()) {
                throw new ExchangeRateException('Invalid quote currency: ' + q);
            }
            normalizedQuotes.add(qNorm);
        }

        if (normalizedQuotes.isEmpty()) {
            throw new ExchangeRateException('Quote currencies set is empty');
        }

        List<String> quoteList = new List<String>(normalizedQuotes);
        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base='
            + EncodingUtil.urlEncode(baseNorm, 'UTF-8')
            + '&symbols='
            + EncodingUtil.urlEncode(String.join(quoteList, ','), 'UTF-8');

        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }

        Integer status = res.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException('Unexpected status code: ' + status);
        }

        String body = res.getBody();
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Empty response body');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        try {
            RateResponse resp = (RateResponse) JSON.deserialize(body, RateResponse.class);
            if (resp == null || resp.rates == null) {
                throw new ExchangeRateException('Invalid response format: missing rates');
            }
            for (String q : normalizedQuotes) {
                Decimal rate = resp.rates.get(q);
                if (rate == null) {
                    throw new ExchangeRateException('Missing rate for currency: ' + q);
                }
                result.put(q, rate);
            }
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Failed to parse response: ' + e.getMessage());
        }

        return result;
    }
}
