public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {}
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object API name and field API name must be non-blank');
        }

        String objName = objectApiName.trim();
        String fldName = fieldApiName.trim();

        // Find object case-insensitively
        Schema.SObjectType objType = null;
        for (String key : Schema.getGlobalDescribe().keySet()) {
            if (key.equalsIgnoreCase(objName)) {
                objType = Schema.getGlobalDescribe().get(key);
                break;
            }
        }
        if (objType == null) {
            throw new PicklistServiceException('Object ' + objName + ' does not exist');
        }

        Schema.DescribeSObjectResult sObjDescribe = objType.getDescribe();
        Map<String, Schema.SObjectField> fieldsMap = sObjDescribe.fields.getMap();

        // Find field case-insensitively
        Schema.SObjectField fieldToken = null;
        for (String key : fieldsMap.keySet()) {
            if (key.equalsIgnoreCase(fldName)) {
                fieldToken = fieldsMap.get(key);
                break;
            }
        }
        if (fieldToken == null) {
            throw new PicklistServiceException('Field ' + fldName + ' does not exist on ' + sObjDescribe.getName());
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field ' + fldName + ' on ' + sObjDescribe.getName() + ' is not a picklist');
        }

        List<Option> results = new List<Option>();

        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            Option opt = new Option();
            opt.value = entry.getValue();
            opt.label = entry.getLabel();
            opt.isDefault = entry.isDefaultValue();
            results.add(opt);
        }

        return results;
    }
}
