        //            2000*25/100 = 500.00
        //            1*33/100     = 0.33  (rounded per opportunity)
        //            nulls ignored
        System.assertEquals(1000.33, result.get('Prospecting'), 'Prospecting total incorrect');

        // Qualification: 5000*20/100 = 1000.00
        System.assertEquals(1000.00, result.get('Qualification'), 'Qualification total incorrect');

