public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
    }

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Map<String, Schema.FieldSet> fsMap = Schema.SObjectType.Account.fieldSets.getMap();
        Schema.FieldSet creditReviewFs = fsMap.get('Credit_Review');
        if (creditReviewFs != null) {
            for (Schema.FieldSetMember fsm : creditReviewFs.getFields()) {
                String fieldName = fsm.getFieldPath();
                Schema.SObjectField sfield = Schema.SObjectType.Account.fields.getMap().get(fieldName);
                if (sfield != null && !fields.contains(sfield)) {
                    fields.add(sfield);
                }
            }
        }
        return fields;
    }

    public override List<SObject> selectSObjectsById(Set<Id> ids) {
        if (ids == null || ids.isEmpty()) {
            return new List<SObject>();
        }
        fflib_QueryFactory factory = new fflib_QueryFactory(getSObjectType());
        factory.setAccessLevel(System.AccessLevel.USER_MODE);
        factory.selectFields(getSObjectFieldList());
        factory.setCondition('Id IN :ids');
        return Database.query(factory.toSOQL());
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        fflib_QueryFactory factory = new fflib_QueryFactory(getSObjectType());
        factory.setAccessLevel(System.AccessLevel.USER_MODE);
        factory.selectFields(getSObjectFieldList());

        ContactsSelector contactsSelector = new ContactsSelector();
        List<Schema.SObjectField> contactFields = contactsSelector.getSObjectFieldList();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField cf : contactFields) {
            contactFieldNames.add(cf.getDescribe().getName());
        }
        String contactSubQuery = 'SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contact';
        factory.addSubQuery('Contacts', contactSubQuery);

        factory.setCondition('Id IN :accountIds');
        return (List<Account>) Database.query(factory.toSOQL());
    }
}
