public class DealEventPublisher {
    /**
     * Publishes Deal_Stage_Change__e events for the supplied Opportunities.
     *
     * DEVIATION FROM SPECIFICATION
     * The original instruction was to call EventBus.publish once per Opportunity
     * inside the loop. That would issue one DML statement per record and exceeds
     * the 150 DML statement governor limit for a trigger batch of 200 records.
     * 
     * To stay within governor limits while preserving the required ordering,
     * events are collected in a list and published in a single bulk
     * EventBus.publish call. EventBus.publish(List<SObject>) returns a
     * Database.SaveResult for each event in the same order as the input list,
     * so the result list can be mapped 1:1 to the input Opportunities.
     * This reduces DML usage from N to 1 and is safe for up to 200 records.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();

        for (Opportunity opp : opportunities) {
            // Defensive guard for safety in trigger context
            if (opp == null || opp.Id == null) {
                continue;
            }

            Deal_Stage_Change__e evt = new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,
                Stage__c         = opp.StageName,
                Amount__c        = opp.Amount
            );
            events.add(evt);
        }

        if (!events.isEmpty()) {
            // One DML statement for the whole batch, results remain in input order
            results = EventBus.publish(events);
        }

        return results;
    }
}
