public with sharing class LineItemDiscountHandler {
    public static void applyStandardDiscount(List<OpportunityLineItem> newItems) {
        Map<Id, Decimal> discountCache = new Map<Id, Decimal>();

        for (OpportunityLineItem line : newItems) {
            if (line.Discount == null && line.Product2Id != null) {
                Id pid = line.Product2Id;
                if (!discountCache.containsKey(pid)) {
                    try {
                        // Single source of truth – PricingRules owns the logic
                        discountCache.put(pid, PricingRules.standardDiscountFor(pid));
                    } catch (Exception e) {
                        // Product not found / inaccessible – default to 0% rather than leave null
                        discountCache.put(pid, 0);
                    }
                }
                line.Discount = discountCache.get(pid);
            }
        }
    }
}
