public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        if (leads == null) {
            return new List<Id>();
        }
        if (contacts == null) {
            contacts = new List<Contact>();
        }

        // Build map of normalized email -> first Contact Id in contacts order
        Map<String, Id> emailToContactId = new Map<String, Id>();
        for (Contact con : contacts) {
            if (con == null) {
                continue;
            }
            String email = con.Email;
            if (String.isBlank(email)) {
                continue;
            }
            String norm = email.trim().toLowerCase();
            if (!emailToContactId.containsKey(norm)) {
                emailToContactId.put(norm, con.Id);
            }
        }

        List<Id> result = new List<Id>();
        for (Lead lead : leads) {
            if (lead == null || String.isBlank(lead.Email)) {
                result.add(null);
                continue;
            }
            String normLead = lead.Email.trim().toLowerCase();
            Id matched = emailToContactId.get(normLead);
            result.add(matched);
        }
        return result;
    }
}
