public class RenewalReminderService {

    /*
     * The original request to call Messaging.sendEmail once per opportunity
     * inside a loop is a bad idea. Each Messaging.sendEmail invocation counts
     * against the per-transaction Email Invocations limit (10 per transaction)
     * and adds CPU / call overhead. With up to 200 opportunities this will
     * throw System.LimitException: Too many Email Invocations and will also
     * hit the 100 emails per transaction limit. The correct pattern is to
     * build all SingleEmailMessage instances and send them in bulk, chunked
     * to <=100 messages per sendEmail call, then inspect SendEmailResult[].
     */

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        List<Messaging.SingleEmailMessage> mails = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opps) {
            if (opp.OwnerId == null) {
                continue;
            }
            // Only Users can be targeted directly
            if (!String.valueOf(opp.OwnerId).startsWith('005')) {
                continue;
            }

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setTreatTargetObjectAsRecipient(true);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);

            String closeDateText = opp.CloseDate != null ? String.valueOf(opp.CloseDate) : 'unknown date';
            String body = 'Hello,\n\n'
                + 'The opportunity "' + opp.Name + '" has a renewal due on ' + closeDateText + '.\n'
                + 'Please review the record and take the required action.\n\n'
                + 'Thanks';
            mail.setPlainTextBody(body);

            mails.add(mail);
        }

        if (mails.isEmpty()) {
            return 0;
        }

        Integer sentCount = 0;
        Integer batchSize = 100; // max emails per sendEmail call

        for (Integer i = 0; i < mails.size(); i += batchSize) {
            Integer endIdx = Math.min(i + batchSize, mails.size());
            List<Messaging.SingleEmailMessage> batch = mails.subList(i, endIdx);
            Messaging.SendEmailResult[] results = Messaging.sendEmail(batch);
            if (results != null) {
                for (Messaging.SendEmailResult res : results) {
                    if (res.isSuccess()) {
                        sentCount++;
                    }
                }
            }
        }

        return sentCount;
    }
}
