import { LightningElement, wire } from 'lwc';
import { MessageContext, subscribe, unsubscribe, publish, APPLICATION_SCOPE } from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext)
    wiredContext(context) {
        this.messageContext = context;
        if (context && !this.subscription) {
            this.subscribeToChannel();
        }
    }

    messageContext;
    subscription = null;
    accountId = null;

    subscribeToChannel() {
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    disconnectedCallback() {
        if (this.subscription) {
            unsubscribe(this.messageContext, this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        this.accountId = message && message.recordId ? message.recordId : null;
    }

    handleClick(event) {
        if (event.currentTarget.dataset.action === 'clear') {
            this.publishClear();
        }
    }

    publishClear() {
        if (this.messageContext) {
            publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
        }
    }
