public class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        npsp__DataImportBatch__c batch = new npsp__DataImportBatch__c();
        batch.Name = 'WebGift_' + DateTime.now().getTime();
        insert batch;

        List<npsp__DataImport__c> diList = new List<npsp__DataImport__c>();
        for (WebGift g : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__DataImportBatch__c = batch.Id;
            di.npsp__Source__c = 'Web';
            di.npsp__Contact1_Firstname__c = g.firstName;
            di.npsp__Contact1_Lastname__c = g.lastName;
            di.npsp__Contact1_Personal_Email__c = g.email;
            di.npsp__Donation_Amount__c = g.amount;
            di.npsp__Donation_Date__c = g.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';
            diList.add(di);
        }
        insert diList;

        List<Id> diIds = new List<Id>();
        for (npsp__DataImport__c di : diList) {
            diIds.add(di.Id);
        }

        try {
            npsp.DataImportService.processDataImportRecords(diIds);
        } catch (Exception e) {
            for (Integer i = 0; i < gifts.size(); i++) {
                ImportResult ir = new ImportResult();
                ir.success = false;
                ir.contactId = null;
                ir.opportunityId = null;
                ir.errorMessage = 'Processing error: ' + e.getMessage();
                results.add(ir);
            }
            return results;
        }

        Map<Id, npsp__DataImport__c> diMap = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :diList
        ]);

        for (Integer i = 0; i < diList.size(); i++) {
            npsp__DataImport__c di = diMap.get(diList[i].Id);
            ImportResult ir = new ImportResult();
            if (di != null && di.npsp__Status__c == 'Imported') {
                ir.success = true;
                ir.contactId = di.npsp__Contact1Imported__c;
                ir.opportunityId = di.npsp__DonationImported__c;
                ir.errorMessage = null;
            } else {
                ir.success = false;
                ir.contactId = di != null ? di.npsp__Contact1Imported__c : null;
                ir.opportunityId = di != null ? di.npsp__DonationImported__c : null;
                ir.errorMessage = di != null ? di.npsp__FailureInformation__c : 'Unknown error';
            }
            results.add(ir);
        }
        return results;
    }
}
