public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            if (req.opportunityId == null || req.contactId == null) continue;
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }
        if (oppIds.isEmpty()) return;

        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        Map<String, npsp__Partial_Soft_Credit__c> existingScMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c sc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            String key = sc.npsp__Opportunity__c + '|' + sc.npsp__Contact__c;
            existingScMap.put(key, sc);
        }

        Map<String, OpportunityContactRole> ocrByRole = new Map<String, OpportunityContactRole>();
        Map<String, OpportunityContactRole> ocrByPair = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            String pairKey = ocr.OpportunityId + '|' + ocr.ContactId;
            String roleKey = pairKey + '|' + String.valueOf(ocr.Role);
            ocrByRole.put(roleKey, ocr);
            if (!ocrByPair.containsKey(pairKey)) {
                ocrByPair.put(pairKey, ocr);
            }
        }

        // Validation - no DML before this point
        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive for opportunity ' + req.opportunityId);
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Role is required for opportunity ' + req.opportunityId);
            }
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c != null && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Contact is primary contact for opportunity ' + req.opportunityId);
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException('Amount exceeds opportunity amount for ' + req.opportunityId);
            }
        }

        // Ensure exactly one OpportunityContactRole per opp/contact with the requested role
        List<OpportunityContactRole> ocrToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrToUpdate = new List<OpportunityContactRole>();
        Map<String, Id> ocrIdByRequestKey = new Map<String, Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            String pairKey = req.opportunityId + '|' + req.contactId;
            String roleKey = pairKey + '|' + req.role;

            OpportunityContactRole existingOcr = ocrByRole.get(roleKey);
            Id ocrId;
            if (existingOcr != null) {
                ocrId = existingOcr.Id;
            } else {
                OpportunityContactRole existingPair = ocrByPair.get(pairKey);
                if (existingPair != null) {
                    existingPair.Role = req.role;
                    ocrToUpdate.add(existingPair);
                    ocrId = existingPair.Id;
                    // update maps for subsequent requests
                    String oldRoleKey = pairKey + '|' + String.valueOf(existingPair.Role);
                    // role already changed, just refresh map
                    ocrByRole.remove(oldRoleKey);
                    ocrByRole.put(roleKey, existingPair);
                } else {
                    OpportunityContactRole newOcr = new OpportunityContactRole(
                        OpportunityId = req.opportunityId,
                        ContactId = req.contactId,
                        Role = req.role,
                        IsPrimary = false
                    );
                    ocrToInsert.add(newOcr);
                    // temporary placeholder, id will be assigned after insert
                    ocrId = null;
                }
            }
            ocrIdByRequestKey.put(pairKey, ocrId);
        }

        if (!ocrToInsert.isEmpty()) {
            insert ocrToInsert;
            // map newly inserted ids back to requests
            for (OpportunityContactRole ocr : ocrToInsert) {
                String pairKey = ocr.OpportunityId + '|' + ocr.ContactId;
                ocrIdByRequestKey.put(pairKey, ocr.Id);
                String roleKey = pairKey + '|' + ocr.Role;
                ocrByRole.put(roleKey, ocr);
                ocrByPair.put(pairKey, ocr);
            }
        }
        if (!ocrToUpdate.isEmpty()) {
            update ocrToUpdate;
        }

        // Upsert partial soft credits
        List<npsp__Partial_Soft_Credit__c> scToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> scToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            if (req == null) continue;
            String pairKey = req.opportunityId + '|' + req.contactId;
            String scKey = pairKey;

            // Resolve OCR Id - if we just inserted, ocrIdByRequestKey has it
            Id ocrId = ocrIdByRequestKey.get(pairKey);
            // If ocrId still null, find from maps
            if (ocrId == null) {
                String roleKey = pairKey + '|' + req.role;
                OpportunityContactRole ocr = ocrByRole.get(roleKey);
                if (ocr != null) ocrId = ocr.Id;
            }

            npsp__Partial_Soft_Credit__c existing = existingScMap.get(scKey);
            if (existing != null) {
                existing.npsp__Amount__c = req.amount;
                existing.npsp__Role_Name__c = req.role;
                if (ocrId != null) existing.npsp__Contact_Role_ID__c = String.valueOf(ocrId);
                scToUpdate.add(existing);
            } else {
                if (ocrId == null) {
                    // Should not happen, skip
                    continue;
                }
                npsp__Partial_Soft_Credit__c sc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(ocrId)
                );
                scToInsert.add(sc);
            }
        }

        if (!scToInsert.isEmpty()) {
            insert scToInsert;
        }
        if (!scToUpdate.isEmpty()) {
            update scToUpdate;
        }
    }
}
