public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required');
        }

        Contact con;
        try {
            con = [
                SELECT Id, FirstName, LastName, AccountId
                FROM Contact
                WHERE Id = :contactId
                LIMIT 1
            ];
        } catch (QueryException qe) {
            throw new IllegalArgumentException('Contact does not exist');
        }

        if (con.AccountId == null) {
            throw new IllegalArgumentException('Contact must belong to a household account');
        }

        String oppName = (con.FirstName != null ? con.FirstName : '') + ' ' +
                         (con.LastName != null ? con.LastName : '') +
                         ' Donation ' + String.valueOf(giftDate);

        Opportunity opp = new Opportunity();
        opp.Name = oppName;
        opp.AccountId = con.AccountId;
        opp.npsp__Primary_Contact__c = con.Id;
        opp.Amount = amount;
        opp.CloseDate = giftDate;
        opp.StageName = 'Closed Won';
        opp.Type = 'Donation';

        try {
            RecordType rt = [
                SELECT Id
                FROM RecordType
                WHERE SObjectType = 'Opportunity' AND DeveloperName = 'Donation'
                LIMIT 1
            ];
            opp.RecordTypeId = rt.Id;
        } catch (Exception e) {
            // RecordType not found – continue without it
        }

        insert opp;

        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :con.AccountId
        ];

        Map<Id, OpportunityContactRole> existingRoles = new Map<Id, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId = :opp.Id
        ]) {
            existingRoles.put(ocr.ContactId, ocr);
        }

        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();

        for (Contact mem : householdMembers) {
            String desiredRole = (mem.Id == con.Id) ? 'Donor' : 'Household Member';
            if (existingRoles.containsKey(mem.Id)) {
                OpportunityContactRole existing = existingRoles.get(mem.Id);
                if (existing.Role != desiredRole) {
                    existing.Role = desiredRole;
                    ocrsToUpdate.add(existing);
                }
            } else {
                OpportunityContactRole ocr = new OpportunityContactRole();
                ocr.OpportunityId = opp.Id;
                ocr.ContactId = mem.Id;
                ocr.Role = desiredRole;
                ocrsToInsert.add(ocr);
            }
        }

        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opp.Id
        ];

        if (existingPayments.isEmpty()) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c();
            payment.npe01__Opportunity__c = opp.Id;
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Scheduled_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            insert payment;
        }

        return opp.Id;
    }
}
