public class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    private static Set<Id> idsToSync = new Set<Id>();

    public static Set<Id> getIdsToSync() {
        return idsToSync;
    }

    public static void clearIdsToSync() {
        idsToSync.clear();
    }

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject sobj : triggerNew) {
            if (sobj instanceof Opportunity) {
                Id oppId = sobj.Id;
                if (oppId != null) {
                    idsToSync.add(oppId);
                }
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Integer size = triggerNew.size();
        for (Integer i = 0; i < size; i++) {
            SObject newSobj = triggerNew[i];
            SObject oldSobj = triggerOld[i];
            if (newSobj instanceof Opportunity && oldSobj instanceof Opportunity) {
                Opportunity newOpp = (Opportunity)newSobj;
                Opportunity oldOpp = (Opportunity)oldSobj;
                if (newOpp.StageName != oldOpp.StageName) {
                    Id oppId = newOpp.Id;
                    if (oppId != null) {
                        idsToSync.add(oppId);
                    }
                }
            }
        }
    }
}
